@once
<template id="flow-person-button"><button type="button" class="person-button"><span class="avatar" data-initials></span><span class="min-w-0 grow"><strong class="block text-[13px] font-semibold" data-name></strong><span class="block text-xs text-muted" data-status></span></span></button></template>
<template id="flow-score-sheet"><section data-score-content><div class="person-heading mb-6 flex flex-wrap items-start gap-4"><span class="avatar size-11!" data-initials></span><div class="min-w-0 grow"><p class="mb-1 text-xs font-semibold text-success" data-kind></p><h2 class="text-xl font-semibold" data-name></h2><p class="mt-1 text-sm text-muted" data-person-meta></p><p class="mt-1 text-xs text-muted" data-template-meta></p></div><span class="status" data-status></span></div><div class="notice notice-warning mb-4" data-return-reason hidden></div><div class="notice mb-4" data-lock-reason hidden></div><div class="table-wrap"><table class="data-table score-table"><thead><tr><th>KPI dan target</th><th class="numeric">Bobot</th><th class="numeric">Nilai</th><th class="numeric">Bulan lalu</th><th class="numeric">Hasil</th></tr></thead><tbody data-score-rows></tbody></table></div><p class="mt-3 text-xs text-muted">Nilai bilangan bulat 10-100. Hasil = nilai x bobot / 100. Total bobot <b data-score-weight></b>%. <span data-filled></span> KPI terisi.</p><div class="my-6 flex flex-wrap items-center justify-end gap-4"><span class="text-sm text-muted">Total nilai</span><strong class="num text-[40px]" data-total></strong><span class="category font-semibold" data-category></span></div><div class="grid gap-4 min-[1100px]:grid-cols-2"><label><span class="label">Temuan positif (opsional)</span><textarea class="field min-h-24" data-finding="positive" maxlength="10000"></textarea><p data-read-finding="positive" class="text-sm leading-6" hidden></p></label><label><span class="label">Temuan negatif (opsional)</span><textarea class="field min-h-24" data-finding="negative" maxlength="10000"></textarea><p data-read-finding="negative" class="text-sm leading-6" hidden></p></label></div><p class="notice notice-error mt-4" data-score-error hidden role="alert"></p></section></template>
<template id="flow-score-item"><tr><td><strong class="font-semibold" data-kpi-name></strong><span class="mt-1 block text-xs text-muted" data-kpi-meta></span></td><td class="numeric" data-label="Bobot" data-weight></td><td class="numeric" data-label="Nilai"><label><span class="sr-only" data-score-label></span><input class="score-input num" type="text" inputmode="numeric" autocomplete="off" maxlength="5" placeholder="-" data-score></label><strong data-read-score hidden></strong></td><td class="numeric text-xs text-muted" data-label="Bulan lalu" data-previous></td><td class="numeric font-semibold" data-label="Hasil" data-result></td></tr></template>
@endonce
